export var minDecimalPrice = function(flt) {
  var d, digits, rounded, roundedStr;
  if (typeof flt !== "number") {
    throw new Error("minDecimalPrice - flt must be a number!");
  }
  rounded = 0.01 * Math.round(100 * flt);
  roundedStr = rounded.toFixed(2);
  digits = roundedStr.split("");
  while (true) {
    d = digits.pop();
    if (d === '0') {
      continue;
    }
    if (d === '.') {
      break;
    }
    digits.push(d);
    break;
  }
  return digits.join("");
};

