export var isLeapYear = function(year) {
  if ((year % 4) !== 0) {
    return false;
  }
  if ((year % 100) === 0 && (year % 400) !== 0) {
    return false;
  }
  return true;
};

export var getDaysOfYear = function(year) {
  if (isLeapYear(year)) {
    return 366;
  } else {
    return 365;
  }
};

export var getLeapYearConfig = function() {
  var currentYear, lastYear, today;
  today = new Date();
  currentYear = today.getFullYear();
  lastYear = currentYear - 1;
  return {
    currentYearIsLeap: isLeapYear(currentYear),
    lastYearIsLeap: isLeapYear(lastYear),
    currentYearDays: getDaysOfYear(currentYear),
    lastYearDays: getDaysOfYear(lastYear)
  };
};

//###########################################################
// Index Conventions:
//   nonLeapNorm (0-364): Jan1=0, Feb28=58, Mar1=59. No Feb29.
//   leapNorm (0-365): Jan1=0, Feb28=58, Feb29=59, Mar1=60.
//   real: actual day-of-year. NonLeap 0-364, Leap 0-365.
export var leapNormToRealIdx = function(normed, isLeap) {
  if (isLeap) { // leap real == leap norm
    return normed;
  }
  if (normed < FEB29) { // 0-58 unchanged
    return normed;
  }
  if (normed === FEB29) { // Feb29 → Feb28
    return FEB28;
  }
  return normed - 1; // 60+ shift down
};

export var nonLeapNormToRealIdx = function(normed, isLeap) {
  if (!isLeap) { // nonLeap real == nonLeap norm
    return normed;
  }
  if (normed < FEB29) { // 0-58 (through Feb28) unchanged
    return normed;
  }
  return normed + 1; // 59+ (Mar1+) shift forward for Feb29
};

export var realToLeapNormIdx = function(real, isLeap) {
  if (isLeap) { // leap real == leap norm
    return real;
  }
  if (real < FEB29) { // 0-58 unchanged
    return real;
  }
  return real + 1; // 59+ shift (skip Feb29 slot)
};

export var realToNonLeapNormIdx = function(real, isLeap) {
  if (!isLeap) { // nonLeap real == nonLeap norm
    return real;
  }
  if (real < FEB29) { // 0-58 unchanged
    return real;
  }
  if (real === FEB29) { // Feb29 → Feb28
    return FEB28;
  }
  return real - 1; // 60+ shift down
};

export var leapNormToYYYYMMDD = function(idx, year) {
  var date, isLeap;
  //# idx is a "normed" idx in the range 0 - 365
  //# leapNorm means that the idx assumes the 366 days of a leap year
  //# this means non-leap years still have an index for February 29 (idx = 59) Which would become February 28 and all later would be idx - 1
  //# isLeapYear(year) tells us if the year is a leap Year
  if (idx <= -733 || idx >= 732) {
    throw new Error("idx out of bounds!");
  }
  //# apply overflow to switch the year appropriately
  year += Math.floor(idx / 366);
  // if idx < 0 then year += Math.ceil(idx / 366)
  // else year += Math.floor(idx / 366)
  isLeap = isLeapYear(year);
  idx = (idx + 732) % 366; // ensure idx is within range
  if (!isLeap && idx >= 59) {
    idx--;
  }
  //# create the date according to the Index
  date = new Date(year, 0, 1, 12, 0, 0);
  date.setDate(date.getDate() + idx);
  //# return the YYYY-MM-DD formated date string
  return date.toISOString().slice(0, 10);
};

export var nonLeapNormToYYYYMMDD = function(idx, year) {
  var date, isLeap;
  //# idx is a "normed" idx in the range 0-364
  //# nonLeapNorm means that the idx assumes the 365 days of a non-leap year
  //# this means leap years have no index for February 29 which should be considered
  //# isLeapYear(year) tells us if the year is a leap Year
  if (idx <= -731 || idx >= 730) {
    throw new Error("idx out of bounds!");
  }
  //# apply overflow to switch the year appropriately
  year += Math.floor(idx / 365);
  // if idx < 0 then year += Math.ceil(idx / 365)
  // else year += Math.floor(idx / 365)
  isLeap = isLeapYear(year);
  idx = (idx + 730) % 365; // ensure idx is within range
  if (isLeap && idx >= 59) {
    idx++;
  }
  //# create the date according to the Index
  date = new Date(year, 0, 1, 12, 0, 0);
  date.setDate(date.getDate() + idx);
  //# return the YYYY-MM-DD formated date string
  return date.toISOString().slice(0, 10);
};

