//###########################################################
// Convenience class to handle day of year with associated index values.
// @nIndex: nonLeapNorm index (0-364) 
// Notice! Legal overflows of -729 to +729 change @year parameter accordingly
// Whenever we have a specific day as (year + nonLeapNorm index) use this class.
export var Day = class Day {
  constructor(nIndex1, year1) {
    this.getDayNextYear = this.getDayNextYear.bind(this);
    this.getDayPrevYear = this.getDayPrevYear.bind(this);
    this.getNextDay = this.getNextDay.bind(this);
    this.getPrevDay = this.getPrevDay.bind(this);
    this.getRelativeDay = this.getRelativeDay.bind(this);
    this.getDateStr = this.getDateStr.bind(this);
    this.getYYYYMMDD = this.getYYYYMMDD.bind(this);
    this.lookupIn = this.lookupIn.bind(this);
    this.nIndex = nIndex1;
    this.year = year1;
    if (this.nIndex <= -730 || this.nIndex >= 730) {
      throw Error(`Invalid nIndex! (${this.nIndex})`);
    }
    this.year += Math.floor(this.nIndex / 365); // apply overflow to change @year
    this.nIndex = (this.nIndex + 2 * 365) % 365; // push overflows to 0-364 range
    this.isLeap = isLeapYear(this.year);
    // @rIndex: real day-of-year index (accounts for leap year)
    this.rIndex = nonLeapNormToRealIdx(this.nIndex, this.isLeap);
    this.yearIdx = (new Date()).getFullYear() - this.year;
    this.daysOfYear = getDaysOfYear(this.year);
  }

  getDayNextYear() {
    return new Day(this.nIndex, this.year + 1);
  }

  getDayPrevYear() {
    return new Day(this.nIndex, this.year - 1);
  }

  getNextDay() {
    return new Day((this.nIndex + 1) % 365, this.year + (this.nIndex === 364));
  }

  getPrevDay() {
    return new Day((this.nIndex + 364) % 365, this.year - (this.nIndex === 0));
  }

  getRelativeDay(num) {
    if (num > 0) {
      return new Day((this.nIndex + num) % 365, this.year + ((this.nIndex + num) > 364));
    } else {
      return new Day((this.nIndex + (365 + num)) % 365, this.year - ((this.nIndex + num) < 0));
    }
  }

  getDateStr() {
    return dayIndexToDateStr(this.year, this.rIndex);
  }

  getYYYYMMDD() {
    var ddmmyyyy, tkns;
    ddmmyyyy = dayIndexToDateStr(this.year, this.rIndex);
    tkns = ddmmyyyy.split(".");
    tkns.reverse();
    return tkns.join("-");
  }

  lookupIn(perYearData) {
    var numMissing, rIndex, yearData;
    yearData = perYearData[this.yearIdx];
    if (yearData == null) {
      return null;
    }
    if (this.yearIdx === 0) { // current Year might be incomplete to the year end
      if (this.rIndex >= yearData.length) {
        return null;
      } else {
        return yearData[this.rIndex];
      }
    }
    numMissing = this.daysOfYear - yearData.length;
    // missing in older years means incomplete from the year start  
    rIndex = this.rIndex - numMissing;
    if (rIndex < 0) {
      return null;
    }
    return yearData[rIndex];
  }

};


