export var scanForFreakValues = function(dataArray, label) {
  var i, j, len, nanIndices, nullCount, undefinedIndices, val;
  if (dataArray == null) {
    console.warn(`[chartfun] ${label}: array is null/undefined`);
    return false;
  }
  if (!Array.isArray(dataArray)) {
    console.warn(`[chartfun] ${label}: not an array, got ${typeof dataArray}`);
    return false;
  }
  nullCount = 0;
  undefinedIndices = [];
  nanIndices = [];
  for (i = j = 0, len = dataArray.length; j < len; i = ++j) {
    val = dataArray[i];
    if (val === null) {
      nullCount++;
    } else if (val === void 0) {
      undefinedIndices.push(i);
    } else if (typeof val === 'number' && isNaN(val)) {
      nanIndices.push(i);
    }
  }
  if (nullCount > 0) {
    console.log(`[chartfun] ${label}: ${nullCount} null values (legal empty)`);
  }
  if (undefinedIndices.length > 0) {
    console.warn(`[chartfun] ${label}: UNDEFINED at indices:`, undefinedIndices);
    return false;
  }
  if (nanIndices.length > 0) {
    console.warn(`[chartfun] ${label}: NaN at indices:`, nanIndices);
    return false;
  }
  return true;
};

