export var lastWeekdayBefore = function(startDate) {
  var dayOfWeek, thisDate;
  thisDate = new Date(startDate);
  dayOfWeek = thisDate.getDay();
  //# 0 is Sunday
  if (dayOfWeek === 0) {
    thisDate.setDate(thisDate.getDate() - 2);
  }
  //# 6 is Saturday
  if (dayOfWeek === 6) {
    thisDate.setDate(thisDate.getDate() - 1);
  }
  return thisDate.toISOString().slice(0, 10);
};

export var nextWeekdayAfter = function(startDate) {
  var dayOfWeek, thisDate;
  thisDate = new Date(startDate);
  dayOfWeek = thisDate.getDay();
  //# 0 is Sunday
  if (dayOfWeek === 0) {
    thisDate.setDate(thisDate.getDate() + 1);
  }
  //# 6 is Saturday
  if (dayOfWeek === 6) {
    thisDate.setDate(thisDate.getDate() + 2);
  }
  return thisDate.toISOString().slice(0, 10);
};

